={{ (() => {
  const t = $json.message?.text || '';
  const low = t.toLowerCase().trim();

  const isGreeting = /^(привет|хай|hello|hi|здарова|добрый|start|старт)\b/i.test(low);

  const flowCmd = /\/engine\s*(flow|gemini)/i.test(t)
    || low.includes('flow')
    || low.includes('флоу')
    || low.includes('на флоу')
    || low.includes('через flow')
    || low.includes('через гугл')
    || low.includes('через google')
    || low.includes('через gemini')
    || low.includes('на гемини')
    || low.includes('сделай на флоу')
    || low.includes('используй flow')
    || low.includes('используй флоу');

  const pollinationsCmd = /\/engine\s*pollinations/i.test(t)
    || low.includes('pollinations')
    || low.includes('полинейшнс')
    || low.includes('пуллинейшнс')
    || low.includes('на pollinations')
    || low.includes('через pollinations');

  const regenerateCmd =
    low.includes('не нравится')
    || low.includes('не понрав')
    || low.includes('переделай')
    || low.includes('сделай другую')
    || low.includes('другую фот')
    || low.includes('ещё вариант')
    || low.includes('еще вариант')
    || low.includes('другой вариант')
    || low.includes('не то')
    || low.includes('сделай иначе')
    || low.includes('заново давай');

  const autopilotCmd =
    low.includes('сделай сам')
    || low.includes('на твой вкус')
    || low.includes('без заморочек')
    || low.includes('не заморачива')
    || low.includes('как лучше')
    || low.includes('сам выбери');

  const promptReadyCmd =
    /(^|\n)\s*(prompt|промпт)\s*[:=]/i.test(t)
    || low.includes('готовый промпт')
    || low.includes('вот промпт')
    || low.includes('есть промпт')
    || low.includes('у меня промпт')
    || (t.length > 220 && (
      low.includes('cinematic')
      || low.includes('lighting')
      || low.includes('style')
      || low.includes('композиц')
      || low.includes('освещен')
    ));

  const videoGoalCmd =
    low.includes('видео')
    || low.includes('ролик')
    || low.includes('video content')
    || low.includes('контент');

  if (!isGreeting && !flowCmd && !pollinationsCmd && !regenerateCmd && !autopilotCmd && !promptReadyCmd && !videoGoalCmd) return t;

  const lines = [];

  if (isGreeting) {
    lines.push(
      'WIZARD_FORCE: начни простой мастер-диалог с выбора движка.',
      'Спроси коротко: 1) Flow 2) Pollinations.'
    );
  }

  if (autopilotCmd) {
    lines.push(
      'AUTOPILOT_FORCE: пользователь просит не заморачиваться.',
      'Применяй дефолты и задай только 1 короткий вопрос по теме/стилю.'
    );
  }

  if (promptReadyCmd) {
    lines.push(
      'PROMPT_READY_FORCE: у пользователя уже есть готовый промпт.',
      'Не запускай полный опрос, уточни только недостающее для фото/видео пайплайна.'
    );
  }

  if (videoGoalCmd) {
    lines.push(
      'VIDEO_GOAL_FORCE: конечная цель пользователя — видео-контент.',
      'Веди пайплайн start/end frame -> video, не останавливайся на одном фото.'
    );
  }

  if (flowCmd) {
    lines.push(
      'FLOW_FORCE: пользователь выбрал движок GEMINI/FLOW.',
      'ОБЯЗАТЕЛЬНО вызови tool geminiNanoBananaAgent в фото-шаге.',
      'Запрещено писать, что gemini вернул ошибку, пока tool не вызван реально.'
    );
  }

  if (pollinationsCmd) {
    lines.push(
      'POLLINATIONS_FORCE: пользователь выбрал движок POLLINATIONS.',
      'ОБЯЗАТЕЛЬНО вызови tool nanoBananaAgent в фото-шаге.'
    );
  }

  if (regenerateCmd) {
    lines.push(
      'REGENERATE_FORCE: пользователь просит новую версию фото.',
      'Используй последний подтверждённый контекст и перегенерируй без полного опроса.'
    );
  }

  lines.push('', 'Текущий ввод пользователя:', t);
  return lines.join('\n');
})(); }}

